namespace OpenIRP.Application.Audit;

public sealed class AuditContext
{
    // Generated by the server, shared within the request/CLI scope. Never taken from arbitrary headers.
    public Guid CorrelationId { get; } = Guid.NewGuid();
}

public sealed record AuditEventView(long Id, Guid? OrganizationId, Guid? ActorUserId, string ActorType,
    string Action, string ResourceType, Guid? ResourceId, string Outcome, Guid CorrelationId,
    string DetailsJson, DateTimeOffset OccurredAt);
public sealed record AuditPage(IReadOnlyList<AuditEventView> Items, long? NextBefore);

public interface IAuditReader
{
    Task<AuditPage> ReadOrganizationAsync(Guid actor, Guid organization, long? before = null, int limit = 50, CancellationToken ct = default);
    Task<AuditPage> ReadGlobalAsync(Guid actor, long? before = null, int limit = 50, CancellationToken ct = default);
}
